<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/espocrm/bootstrap.php';
use Espo\Core\{Application,AclManager,InjectableFactory};
use Espo\Core\ORM\EntityManager;
use Espo\Core\Tenant\{TenantContext,TenantContextStore};
use Espo\Core\Exceptions\{BadRequest,Forbidden,NotFound};
use Espo\Custom\Tools\Consent\CookieConsentService;
use Espo\Custom\Tools\LandingPage\{CustomerPersonalizationService,LandingPageService};

$checks=0;$assert=function(bool $ok,string $message)use(&$checks){$checks++;if(!$ok)throw new RuntimeException($message);};
$deny=function(callable $fn,string $message)use($assert){$denied=false;try{$fn();}catch(BadRequest|Forbidden|NotFound){$denied=true;}$assert($denied,$message);};
$app=new Application();$app->setupSystemUser();$c=$app->getContainer();$em=$c->getByClass(EntityManager::class);
$factory=$c->getByClass(InjectableFactory::class);$contexts=$c->getByClass(TenantContextStore::class);
$a=new TenantContext('30000000-0000-4000-8000-000000000001','isolation-alpha','customer-personalization-test');
$call=fn($fn)=>$contexts->runWith($a,$fn);$tx=$em->getTransactionManager();$tx->start();
try {
    $suffix=bin2hex(random_bytes(5));
    $make=fn($type,$label='')=>$call(fn()=>$em->createEntity('User',['userName'=>'personalization-'.$type.$label.'-'.$suffix,'emailAddress'=>'personalization-'.$type.$label.'-'.$suffix.'@example.test','type'=>$type,'isActive'=>true]));
    $admin=$make('admin');$staff=$make('regular');
    $admin=$call(fn()=>$em->getEntityById('User',$admin->getId()));$staff=$call(fn()=>$em->getEntityById('User',$staff->getId()));
    $build=fn($class,$user)=>$factory->createWith($class,['user'=>$user,'acl'=>$c->getByClass(AclManager::class)->createUserAcl($user)]);
    $service=$build(CustomerPersonalizationService::class,$admin);$cookies=$build(CookieConsentService::class,$admin);
    $contact=$call(fn()=>$em->createEntity('Contact',['firstName'=>'Personalization','lastName'=>$suffix,'leadStatus'=>'New']));
    $pages=$factory->create(LandingPageService::class);
    $page=$call(fn()=>$pages->save((object)['name'=>'Customer test','slug'=>'customer-'.$suffix,'locale'=>'en','blocks'=>[(object)['id'=>'hero','type'=>'hero','heading'=>'Default offer','text'=>'Public content','personalization'=>(object)['field'=>'customer:leadStatus','value'=>'New','heading'=>'Customer offer','text'=>'Known customer content']]]]));
    $call(fn()=>$pages->publish($page['id']));
    $visitor='12345678-1234-4234-8234-'.bin2hex(random_bytes(6));
    $resolve=(object)['pageId'=>$page['id'],'visitorKey'=>$visitor];
    $identify=(object)['visitorKey'=>$visitor,'contactId'=>$contact->getId(),'method'=>'authenticated_session','reference'=>'website-session-'.$suffix];
    $assert($call(fn()=>$service->resolve($resolve))['blocks'][0]['heading']==='Default offer','Unknown visitors receive default content.');
    $assert(!$call(fn()=>$service->identify($identify))['verified'],'Identity requires current optional consent.');
    $workspace=$call(fn()=>$cookies->getWorkspace());$banner=$workspace['banner'];$banner['isPublished']=true;
    $call(fn()=>$cookies->save((object)$banner));
    $receipt=function(bool $allow,bool $gpc=false)use($call,$cookies,$banner,$visitor){return $call(fn()=>$cookies->recordReceipt((object)['publicKey'=>$banner['publicKey'],'visitorId'=>$visitor,'receiptKey'=>'12345678-1234-4234-8234-'.bin2hex(random_bytes(6)),'choice'=>'custom','categories'=>(object)['preferences'=>$allow,'advertising'=>$allow],'globalPrivacyControl'=>$gpc]));};
    $receipt(true);
    $assert($call(fn()=>$cookies->allowsPersonalization($visitor)),'Current preferences and advertising receipt permits personalization.');
    $assert($call(fn()=>$service->identify($identify))['verified'],'Authorized backend can verify a consented visitor.');
    $result=$call(fn()=>$service->resolve($resolve));
    $assert($result['blocks'][0]['heading']==='Customer offer','Verified customers receive published matching content.');
    $assert(!str_contains(json_encode($result),$contact->getId())&&!str_contains(json_encode($result),$visitor),'Responses must not expose customer identifiers.');
    $api=$make('api');
    $role=$call(fn()=>$em->createEntity('Role',['name'=>'Personalization API '.$suffix,'data'=>['Contact'=>['read'=>'all','edit'=>'no','create'=>'no','delete'=>'no']]]));
    $call(fn()=>$em->getRDBRepository('User')->getRelation($api,'roles')->relate($role));
    $api=$call(fn()=>$em->getEntityById('User',$api->getId()));$integration=$build(CustomerPersonalizationService::class,$api);
    $assert($call(fn()=>$integration->resolve($resolve))['blocks'][0]['heading']==='Default offer','An integration cannot reuse another issuer identity proof.');
    $assert($call(fn()=>$integration->identify($identify))['verified'],'A native API user with Contact read permission can identify a customer.');
    $assert($call(fn()=>$integration->resolve($resolve))['blocks'][0]['heading']==='Customer offer','Authorized native API users can resolve their own verified customer.');
    $hiddenRole=$call(fn()=>$em->createEntity('Role',['name'=>'Personalization hidden status '.$suffix,'data'=>['Contact'=>['read'=>'all','edit'=>'no','create'=>'no','delete'=>'no']],'fieldData'=>['Contact'=>['leadStatus'=>['read'=>'no','edit'=>'no']]]]));
    $limited=$make('api','-limited');
    $call(fn()=>$em->getRDBRepository('User')->getRelation($limited,'roles')->relate($hiddenRole));
    $limited=$call(fn()=>$em->getEntityById('User',$limited->getId()));$restricted=$build(CustomerPersonalizationService::class,$limited);
    $assert($call(fn()=>$restricted->identify($identify))['verified'],'A readable Contact can be identified without permission to every field.');
    $assert($call(fn()=>$restricted->resolve($resolve))['blocks'][0]['heading']==='Default offer','Hidden fields cannot select personalized content.');
    $pdo=$em->getPDO();
    $expire=$pdo->prepare('UPDATE nexa_personalization_identity_proof SET expires_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 SECOND) WHERE tenant_id=? AND service_id=? AND issuer_user_id=?');
    $expire->execute([$a->tenantId,$a->serviceId,$api->getId()]);
    $assert($call(fn()=>$integration->resolve($resolve))['blocks'][0]['heading']==='Default offer','Expired proof cannot select private variants.');
    $api->set('isActive',false);
    $deny(fn()=>$call(fn()=>$integration->resolve($resolve)),'Inactive integration users cannot resolve customer content.');
    $api->set('isActive',true);
    $b=new TenantContext('30000000-0000-4000-8000-000000000002','isolation-beta','customer-personalization-test');
    $deny(fn()=>$contexts->runWith($b,fn()=>$service->resolve($resolve)),'A mismatched tenant context cannot resolve another workspace page.');
    $foreign=$contexts->runWith($b,fn()=>$em->createEntity('Contact',['firstName'=>'Foreign','lastName'=>$suffix]));
    $deny(fn()=>$call(fn()=>$service->identify((object)array_replace((array)$identify,['contactId'=>$foreign->getId()]))),'Identity proof cannot bind a foreign tenant Contact.');
    $stored=$pdo->prepare('SELECT evidence_hash,expires_at,verified_at FROM nexa_personalization_identity_proof WHERE tenant_id=? AND service_id=? AND issuer_user_id=?');
    $stored->execute([$a->tenantId,$a->serviceId,$admin->getId()]);$proof=$stored->fetch(PDO::FETCH_ASSOC);
    $assert($proof && strlen($proof['evidence_hash'])===64 && !str_contains(json_encode($proof),$identify->reference),'Proof stores a digest rather than raw session evidence.');
    $assert($call(fn()=>$service->resolve((object)((array)$resolve+['privacyControl'=>true])))['blocks'][0]['heading']==='Default offer','GPC forces default content.');
    $deny(fn()=>$call(fn()=>$service->resolve((object)((array)$resolve+['contactId'=>$contact->getId()]))),'Resolve must reject browser-supplied CRM identifiers.');
    $regular=$build(CustomerPersonalizationService::class,$staff);
    $deny(fn()=>$call(fn()=>$regular->identify($identify)),'Regular CRM users cannot issue website identity proof.');
    $call(fn()=>$service->revoke((object)['visitorKey'=>$visitor]));
    $assert($call(fn()=>$service->resolve($resolve))['blocks'][0]['heading']==='Default offer','Revocation immediately restores default content.');
    $call(fn()=>$service->identify($identify));
    $receipt(false);
    $assert($call(fn()=>$service->resolve($resolve))['blocks'][0]['heading']==='Default offer','Withdrawal invalidates an otherwise valid identity proof.');
    echo "Customer personalization checks passed: $checks (rollback-only).\n";
} catch (Throwable $error) {
    fwrite(STDERR,get_class($error).': '.$error->getMessage()."\n".$error->getTraceAsString()."\n");
    throw $error;
} finally {$tx->rollback();}
